// ---------------------------------------------------------------------
// WF-07 step 1: validate the request + build a compliance-safe prompt.
// RULE: never invent financial/insurance/legal/regulatory claims.
// Returns __skip=true when the platform is unsupported.
// ---------------------------------------------------------------------
const j = $input.first().json;
const ALLOWED = ['youtube', 'instagram', 'facebook', 'website', 'whatsapp', 'blog'];
const platform = String(j.platform || '').toLowerCase();
const topic = String(j.topic || '').trim();

if (!ALLOWED.includes(platform) || !topic) {
  return [{ json: { ...j, __skip: true, __reason: 'INVALID_REQUEST', platform, topic } }];
}

const prompt = [
  'You are the Fortune U Group content assistant (Tirupati, India) — insurance + mutual-fund education.',
  'Brand voice: honest, plain-language, compliant. Platform: ' + platform + '.',
  'Topic: ' + topic,
  j.brief ? 'Extra brief: ' + j.brief : '',
  'Produce educational content ONLY.',
  'Never invent returns, guarantees, premiums, IRDAI/SEBI/AMFI claims, statistics, or testimonials.',
  'If a statement needs verification, wrap it with [FACT_CHECK].',
  'Return STRICT JSON only, no markdown fences, with keys:',
  '{title, hook, body, hashtags (array), cta, flags (array of strings)}',
].filter(Boolean).join('\n');

return [{ json: { ...j, platform, topic, __prompt: prompt, __skip: false } }];

// ---------------------------------------------------------------------
// WF-07 step 2: parse the LLM output, detect [FACT_CHECK] claims.
// ---------------------------------------------------------------------
const j = $('Build Prompt').first().json;
if (j.__skip) return [{ json: { ...j, status: 'BLOCKED', __skip: true } }];

const raw = String($input.first()?.json?.candidates?.[0]?.content?.parts?.[0]?.text || '');
let parsed = {};
try { parsed = JSON.parse(raw.replace(/^```json|```$/g, '').trim()); }
catch (e) { parsed = { raw_text: raw }; }

const body = String(parsed.body || parsed.raw_text || raw);
const flags = Array.isArray(parsed.flags) ? parsed.flags : [];
const needsFactCheck = /\[FACT_CHECK\]/i.test(body) || flags.length > 0;

return [{ json: {
  ...j,
  title: parsed.title || j.topic,
  hook: parsed.hook || '',
  body,
  hashtags: Array.isArray(parsed.hashtags) ? parsed.hashtags.join(' ') : '',
  cta: parsed.cta || '',
  flags,
  fact_check: needsFactCheck ? 'FLAGGED' : 'PASSED',
  status: 'DRAFT',
} }];
